# Additions are EXACTLY the set of bg cells covered by chosen stamps; stamps never paint existing non-bg cells;
# a chosen stamp must be anchored so its matching-color cell sits ON a singleton pixel? or free?
# Test: exhaustive search of stamp sets covering adds exactly, then infer anchoring rule.
def solve(n, allow_free_anchor=False):
    a=np.array(G['Demo pair %d input'%n]); b=np.array(G['Demo pair %d output'%n])
