    cs=comps_multi(a.tolist(),bg)
    singles=[tuple(c[0]) for c in cs if len(c)==1]
    tmpls=[[(p-min(p for p,_,_ in c), q-min(q for _,q,_ in c), v) for p,q,v in c] for c in cs if len(c)>1]
    adds={((r,c),int(b[r][c])) for r in range(H) for c in range(W) if a[r][c]==bg and b[r][c]!=bg}
    # candidate placements: footprints subset of {(r,c): a==bg} ∪ {cells where a==b} ; painted bg cells ⊆ adds and must be exactly adds
    cands=[]
    for ti,tshape in enumerate(tmpls):
        for vi,var in enumerate(diheds([(r,c,v) for r,c,v in tshape])):
            for sr in range(H):
                for sc in range(W):
                    fp=[(sr+r,sc+c) for r,c,_ in var]
                    bad=False
                    for (r,c) in fp:
                        if not(0<=r<H and 0<=c<W): bad=True;break
                        if a[r][c]==bg and (sr+r,sc+c) not in {(r,c) for r,c in []}: pass
                    # constraint: bg footprint cells must all become adds; non-bg footprint cells must agree color and stay
                    ok=True
                    pb={}
                    for (r,c) in fp:
                        if a[r][c]==bg:
                            if (r,c) not in {(r2,c2) for r2,c2,_ in adds} or pb.setdefault((r,c),None)!=v:=var[0] if False else None:
                                pass
                    # redo cleanly
                    ok=True; pbset=set()
                    for (r,c) in fp:
                        if a[r][c]==bg:
                            if (r,c) not in {(r2,c2) for r2,c2 in adds}: ok=False;break
                            pbset.add((r,c,int(b[r][c])))
                        elif a[r][c]!=b[r][c]: ok=False;break
                    if ok: cands.append((ti,vi,sr,sc,sorted(pbset)))
    # exact cover: choose subset of cands whose pbsets partition adds
    rem=dict(adds)  # cell->must-be-covered count
    sols=[]
    def rec(chosen):
        if not rem:
            sols.append(list(chosen)); return
        # pick a covered-uncovered cell, need cand covering it
        tgt=[k for k,v in rem.items() if v>0]
        if not tgt: return
        r0,c0=addrs=next(iter(tgt))
        for i,can in enumerate(cands):
            if can[4]==set(tgt): continue
            if tgt & can[4]:
                rec(chosen+[can]); 
        break
    rec([])
    print('demo',n,'num covers:',len(sols),'first:',sols[:2])
