from collections import deque
def comps_of(g):
    g=g.copy(); out=[]
    seen=np.zeros_like(g,bool); dirs=((1,0),(-1,0),(0,1),(0,-1))
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if seen[i,j]: continue
            q=deque([(i,j)]); seen[i,j]=1; cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in dirs:
                    u,v=x+dx,y+dy
                    if 0<=u<g.shape[0] and 0<=v<g.shape[1] and not seen[u,v] and g[u,v]==g[i,j]:
                        seen[u,v]=1; q.append((u,v))
            if len(cells)==1: out.append(('seed',cells[0],int(g[cells[0]])))
            else: out.append(('tmpl',tuple(sorted(cells)),int(g[cells[0]][0])))
    return out
