def solve(n, verbose=False):
    a=np.array(G['Demo pair %d input'%n]); b=np.array(G['Demo pair %d output'%n])
    H,W=a.shape
    objs,bg=comps(a)
    tmpls=[dict(t) for t in [{tuple(sorted(p)):int(a[p[0],p[1]]) for p in sorted(o)} for o in objs if len(o)>1]]
    seeds=[(o[0][0],o[0][1],int(a[o[0][0],o[0][1]])) for o in objs if len(o)==1]
    adds={(i,j):int(b[i,j]) for i in range(H) for j in range(W) if a[i,j]!=b[i,j]}
    # gather all adds; then for each seed compute candidate placements (template,variant,seed->anchor mapping)
    cands=[]  # (seedid -> list of (tmpl_norm, var_norm, set of newcells covered beyond seed))
    for si,sj,sc in seeds:
        opts=[]
        for ti,tmpl in enumerate(tmpls):
            anchors=[(ap,cl) for ap,cl in tmpl.items() if cl==sc]
