                for var in dihed_variants(rels):
                    ok=True
                    newset=[]
                    for (dr,dc),col in var:
                        rr,cc=si+dr,sj+dc
                        if not(0<=rr<H and 0<=cc<W): ok=False;break
                        cur=int(a[rr,cc])
                        if cur!=bg and cur!=col: ok=False;break
                        if cur==bg: newset.append((rr,cc))
                    if ok:
                        # does this placement explain some adds?
                        covers={p for p in newset if p in adds}
                        opts.append((ti,var,newset,tuple(covers),len(newset)-len(covers))
                                  if covers else (ti,var,newset,set(),len(newset)))
                        opts[-1][3]=tuple([p for p in newset if p in adds])
        # keep only opts whose cover is nonempty
        good=[o for o in opts if o[3]]
        cands.append(good)
        if verbose: print('demo',n,'seed',(si,sj),'ngood',len(good),'of',len(opts))
    return a,b,tmpls,seeds,adds,cands,H,W
